update public.project_contacts set
  linkedin_connect_message = $$Hi Casey, your move to Penta and mandate across GTM, brand, and commercial architecture stood out. I build commercial growth systems that connect strategy, customer intelligence, RevOps, and execution. I would value connecting.$$,
  intro_message = $$Thanks for connecting, Casey. Based on your work as Chief Growth Officer at Penta Group, I wanted to be direct about why I reached out. RevHub helps organizations connect customer and market intelligence, segmentation, pricing, marketing, sales execution, operations, forecasting and executive reporting into one commercial growth system. For Penta Group, the opportunity I see is: RevHub can help Casey accelerate Penta's next growth phase by connecting GTM strategy, customer and market intelligence, CRM governance, forecasting, and executive measurement before the internal RevOps build is complete. Would you be open to a quick 15-minute call to discuss what we do and whether it could support your priorities?$$,
  follow_up_message = $$Hi Casey, following up in case my earlier note got buried. I outlined the commercial growth approach behind RevHub here: https://aboutchad.com/approach. Based on your role at Penta Group, I believe there may be a relevant opportunity around new cgo leading global gtm, brand narrative, and commercial architecture while penta is hiring a revenue operations manager to build systems, reporting, forecasting, and data quality. Would you be open to a quick 15-minute call to discuss the approach and whether it could be useful to your team?$$
where lower(contact_name) = lower('Casey Foss') and company = 'Penta Group';

